    def is_mentsu(a, b, c):
        # Koutsu: Three identical tiles
        if a == b == c:
            return True
        # Shuntsu: Three sequential tiles of the same suit
        if a[1] == b[1] == c[1]:
            # Extract numbers and sort them to check for sequence
            nums = sorted([int(a[0]), int(b[0]), int(c[0])])
            if nums[0] + 1 == nums[1] and nums[1] + 1 == nums[2]:
                return True
        return False

    # Helper function to check if two tiles form 2/3 of a mentsu
    def is_two_thirds(a, b):
        # Two identical tiles (2/3 of a koutsu)
        if a == b:
            return True
        # Same suit and difference <= 2 (2/3 of a shuntsu)
        if a[1] == b[1]:
            # Numbers are equal (already covered by a==b) or have a gap of 1 or 2
            if abs(int(a[0]) - int(b[0])) <= 2:
                return True
        return False

    # Case 0: Tokitsukaze already has a mentsu
    if is_mentsu(t1, t2, t3):
        print(0)
    # Case 1: Tokitsukaze needs 1 more tile to complete a mentsu
    elif is_two_thirds(t1, t2) or is_two_thirds(t1, t3) or is_two_thirds(t2, t3):
        print(1)
    # Case 2: Tokitsukaze needs 2 more tiles to complete a mentsu
    else:
        print(2)

