import sys

def solve():
    # Read input from standard input
    line = sys.stdin.readline()
    if not line:
        return

    # Parse n, k, and t
    try:
        n, k, t = map(int, line.split())
    except ValueError:
        return

    # Phase 1: Spectators are standing up one by one until k people are standing
    if t <= k:
        print(t)
    # Phase 2: One person stands up and one person sits down, keeping the count at k
    elif t <= n:
        print(k)
    # Phase 3: No more people stand up, spectators continue sitting down until 0
    else:
        # t > n, so number of people standing is k - (t - n)
        print(k - (t - n))

if __name__ == '__main__':
    solve()

